<script setup lang="ts">import { computed } from 'vue'; import { useUiKit } from '../../platform/uiKit'; import type { UiPermissionInput } from '../../platform/types'; const props = withDefaults(defineProps<{ permission?: UiPermissionInput; any?: string[]; all?: string[]; mode?: 'hide' | 'disable' }>(), { mode: 'hide' }); const ui = useUiKit(); const allowed = computed(() => ui.can(props.permission) && ui.can(props.any?.length ? { any: props.any } : undefined) && ui.can(props.all?.length ? { all: props.all } : undefined));</script>
<template><slot v-if="allowed" :allowed="true" /><template v-else-if="mode === 'disable'"><div class="ui-permission-disabled" aria-disabled="true" inert><slot :allowed="false" /></div></template><slot v-else name="fallback" /></template>
